mapper.update:
UPDATE tb_admin
SET role_ids = #{roleIds},
    role_codes = #{roleCodes}
WHERE admin_id = #{userId}

mapper.select:
SELECT COUNT(*) FROM tb_role
WHERE role_code = #{roleCode} AND delete_yn = 'N'
AND role_id <> #{excludeId}

mapper.update:
UPDATE tb_role
SET site_id = #{siteId}, site_code = #{siteCode},
    parent_role_id = #{parentRoleId}, role_code = #{roleCode},
    role_name = #{roleName}, description = #{description},
    sort_order = #{sortOrder}, use_yn = #{useYn}
WHERE role_id = #{roleId}

UPDATE tb_member
SET role_ids = #{roleIds}
WHERE member_id = #{userId}
